	}

	// 超出预估值或负数：拒绝且保留预留。
	if _, err := w.Settle("u1", "r1", 21); !errors.Is(err, ErrSettleTooLarge) {
		t.Fatalf("over-estimate settle err = %v", err)
	}
	if _, err := w.Settle("u1", "r1", -1); !errors.Is(err, ErrInvalidAmount) {
		t.Fatalf("negative settle err = %v", err)
